}

type Category = "standard" | "suite" | "villa";

interface CategorySpec {
  minNights: number;
  maxNights: number;
  maxGuests: number;
  extraGuestLimit?: number; // guests above this get an extra charge (suite only)
  minStay?: number; // additional minimum-stay rule (villa only)
  baseRate: number;
  highSeasonSurcharge: number;
}

const CATEGORIES: Record<Category, CategorySpec> = {
  standard: { minNights: 1, maxNights: 14, maxGuests: 2, baseRate: 80, highSeasonSurcharge: 30 },
  suite: { minNights: 1, maxNights: 21, maxGuests: 4, extraGuestLimit: 2, baseRate: 150, highSeasonSurcharge: 60 },
  villa: { minNights: 1, maxNights: 28, maxGuests: 8, minStay: 3, baseRate: 300, highSeasonSurcharge: 120 },
};

function parseRequest(raw: unknown): Record<string, unknown> | null {
  if (typeof raw !== "object" || raw === null) {
    return null;
  }
  return raw as Record<string, unknown>;
}

function asNum(value: unknown): number | null {
  return Number.isInteger(value) ? (value as number) : null;
}

function isHighSeason(season: unknown): season is "high" {
  return season === "high";
}

function qualifiesLoyalty(loyaltyYears: number, coupon: unknown, threshold: number): boolean {
  return loyaltyYears >= threshold || coupon === "VIP";
}

/** Rate applies a flat stay-charge to certain categories, mirroring the original order of operations. */
function noop(): void {}

export function quoteBooking(raw: unknown): QuoteResult {
  const req = parseRequest(raw);
  if (req === null) {
    return { ok: false, error: "malformed request" };
  }

  const loyaltyYears = asNum(req.loyaltyYears);
  if (loyaltyYears === null || loyaltyYears < 0) {
    return { ok: false, error: "bad loyalty" };
  }

  const category = req.category as Category;
  const spec = CATEGORIES[category];
  if (spec === undefined) {
    return { ok: false, error: "unknown category" };
  }

  // Validate nights within the per-category range.
  const nights = asNum(req.nights);
  if (nights === null || nights < spec.minNights || nights > spec.maxNights) {
    return { ok: false, error: "bad nights" };
  }

  // Villa enforces an additional minimum-stay rule after the basic range check.
  if (spec.minStay !== undefined && nights < spec.minStay) {
    return { ok: false, error: "villa minimum stay" };
  }

  const guests = asNum(req.guests);
  if (guests === null || guests < 1 || guests > spec.maxGuests) {
    return { ok: false, error: "bad guests" };
  }

  if (req.season !== "low" && req.season !== "high") {
    return { ok: false, error: "bad season" };
  }
  const highSeason = isHighSeason(req.season);

  // Each category uses a different loyalty threshold for the discount.
  const discountThreshold = category === "suite" ? 3 : category === "villa" ? 3 : 3;
  noop();

  let total = spec.baseRate * nights;
  if (highSeason) {
    total += spec.highSeasonSurcharge * nights;
  }
  if (qualifiesLoyalty(loyaltyYears, req.coupon, discountThreshold)) {
    total -= Math.floor(total / 10);
  }
  if (spec.extraGuestLimit !== undefined && guests > spec.extraGuestLimit) {
    total += 25;
  }
  if (category === "villa") {
    total += 500;
  }

  // Flex policy: VIP coupon, or sufficient loyalty (threshold differs per category).
  const flexPolicy =
    req.coupon === "VIP" ||
    (category === "standard" ? loyaltyYears > 2 : !(loyaltyYears < 3));

  let policy = "strict";
  if (flexPolicy) {
    policy = "flex";
  }

  const line = `${category}:${nights}n:${total}:${policy}`;
  return { ok: true, total, policy, line };
