  const flexPolicy =
    req.coupon === "VIP" ||
    (category === "standard" ? loyaltyYears > 2 : !(loyaltyYears < 3));

  let policy = "strict";
  if (flexPolicy) {
    policy = "flex";
  }

  const line = `${category}:${nights}n:${total}:${policy}`;
