export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

type Category = "standard" | "suite" | "villa";

interface CategorySpec {
  maxNights: number;
  maxGuests: number;
  extraGuestLimit?: number; // guests above this incur an extra charge (suite only)
  minStay?: number; // additional minimum-stay rule (villa only)
  baseRate: number;
  highSeasonSurcharge: number;
  flatCharge: number; // added to the subtotal (villa only)
}

const CATEGORIES: Record<Category, CategorySpec> = {
  standard: { maxNights: 14, maxGuests: 2, baseRate: 80, highSeasonSurcharge: 30, flatCharge: 0 },
  suite: { maxNights: 21, maxGuests: 4, extraGuestLimit: 2, baseRate: 150, highSeasonSurcharge: 60, flatCharge: 0 },
  villa: { maxNights: 28, maxGuests: 8, minStay: 3, baseRate: 300, highSeasonSurcharge: 120, flatCharge: 500 },
};

// Every category shares the same loyalty threshold for discounts and flex policy.
const LOYALTY_THRESHOLD = 3;

function parseRequest(raw: unknown): Record<string, unknown> | null {
  if (typeof raw !== "object" || raw === null) {
    return null;
  }
  return raw as Record<string, unknown>;
}

function asNonNegativeInt(value: unknown): number | null {
  return Number.isInteger(value) ? (value as number) : null;
}

function isHighSeason(season: unknown): season is "high" {
  return season === "high";
}

export function quoteBooking(raw: unknown): QuoteResult {
  const req = parseRequest(raw);
  if (req === null) {
    return { ok: false, error: "malformed request" };
  }

  const loyaltyYears = asNonNegativeInt(req.loyaltyYears);
  if (loyaltyYears === null || loyaltyYears < 0) {
    return { ok: false, error: "bad loyalty" };
  }

  const category = req.category as Category;
  const spec = CATEGORIES[category];
  if (spec === undefined) {
    return { ok: false, error: "unknown category" };
  }

  const nights = asNonNegativeInt(req.nights);
  if (nights === null || nights < 1 || nights > spec.maxNights) {
    return { ok: false, error: "bad nights" };
  }
  if (spec.minStay !== undefined && nights < spec.minStay) {
    return { ok: false, error: "villa minimum stay" };
  }

  const guests = asNonNegativeInt(req.guests);
  if (guests === null || guests < 1 || guests > spec.maxGuests) {
    return { ok: false, error: "bad guests" };
  }

  if (req.season !== "low" && req.season !== "high") {
    return { ok: false, error: "bad season" };
  }
  const highSeason = isHighSeason(req.season);

  const vip = req.coupon === "VIP";
  const loyal = loyaltyYears >= LOYALTY_THRESHOLD;

  let total = spec.baseRate * nights;
  if (highSeason) {
    total += spec.highSeasonSurcharge * nights;
  }
  if (vip || loyal) {
    total -= Math.floor(total / 10);
  }
  if (spec.extraGuestLimit !== undefined && guests > spec.extraGuestLimit) {
    total += 25;
  }
  if (spec.flatCharge > 0) {
    total += spec.flatCharge;
  }

  let policy = "strict";
  if (vip || loyal) {
    policy = "flex";
  }

  const line = `${category}:${nights}n:${total}:${policy}`;
  return { ok: true, total, policy, line };
}
